migration-guide.before:
use tokio::net::UnixStream;

// Only supports data, NOT file descriptors
let stream = UnixStream::connect("/path/to/socket").await?;
stream.write_all(b"message").await?;

migration-guide.after:
use atomic_capsule::runtime::net::unix_socket::AsyncUnixSocketCapsule;

// Supports both data AND file descriptors
let mut socket = AsyncUnixSocketCapsule::connect(&Path::new("/path/to/socket")).await?;

// Send FDs (Docker-critical feature)
socket.send_fds(&[stdout, stderr])?;

// Receive FDs
let fds = socket.recv_fds().await?;
